164	void setupLookAt(const Vec3& eye, const Vec3& center, const Vec3& up) {
165	    const Vec3 f = normalize(center - eye);
166	    const Vec3 s = normalize(cross(f, up));
167	    const Vec3 u = cross(s, f);
168	    const std::array<float, 16> matrix = {
169	        s.x, u.x, -f.x, 0.0f,
170	        s.y, u.y, -f.y, 0.0f,
171	        s.z, u.z, -f.z, 0.0f,
172	        -dot(s, eye), -dot(u, eye), dot(f, eye), 1.0f,
173	    };
174	    glLoadMatrixf(matrix.data());
175	}
