601	void updatePickups(GameState& game, float dt) {
602	    game.player.rapidFireTimer = std::max(0.0f, game.player.rapidFireTimer - dt);
603	    for (auto& pickup : game.pickups) {
604	        if (!pickup.active) {
605	            continue;
606	        }
607	        const Vec3 bob{0.0f, std::sin(static_cast<float>(game.kills) + pickup.pos.x * 0.05f) * 0.0f, 0.0f};
608	        const Vec3 playerCenter = game.player.pos + Vec3{0.0f, 2.0f, 0.0f};
609	        if (dot(pickup.pos - playerCenter, pickup.pos - playerCenter) <= 16.0f) {
610	            pickup.active = false;
611	            if (pickup.type == PickupType::Health) {
612	                game.player.health = std::min(100.0f, game.player.health + 30.0f);
613	                addImpact(game, pickup.pos, sf::Color(80, 255, 120), 3.8f, 0.25f);
614	            } else {
615	                game.player.rapidFireTimer = 8.0f;
616	                addImpact(game, pickup.pos, sf::Color(90, 180, 255), 3.8f, 0.25f);
617	            }
618	        }
619	    }
620	    game.pickups.erase(
621	        std::remove_if(game.pickups.begin(), game.pickups.end(), [](const Pickup& pickup) {
622	            return !pickup.active;
623	        }),
624	        game.pickups.end());
625	}
