698	void updateEnemies(GameState& game, float dt) {
699	    if (game.won || game.lost) {
700	        return;
701	    }
702	
703	    const float waveSpeedScale = 1.0f + 0.12f * static_cast<float>(game.wave - 1);
704	    const float cooldownScale = std::max(0.55f, 1.0f - 0.08f * static_cast<float>(game.wave - 1));
705	
706	    int aliveCount = 0;
707	    for (auto& enemy : game.enemies) {
708	        if (!enemy.alive) {
709	            continue;
710	        }
711	
712	        ++aliveCount;
713	        enemy.shootCooldown = std::max(0.0f, enemy.shootCooldown - dt);
714	
715	        const Vec3 toPlayer = game.player.pos - enemy.pos;
716	        const Vec3 flatToPlayer{toPlayer.x, 0.0f, toPlayer.z};
717	        const float dist = length(flatToPlayer);
718	        const Vec3 dir = dist > 1e-4f ? flatToPlayer / dist : Vec3{};
719	        enemy.headingDeg = radToDeg(std::atan2(dir.x, dir.z));
720	
721	        const float preferredRange = enemy.type == EnemyType::Tank ? 28.0f : (enemy.type == EnemyType::Sprinter ? 22.0f : kEnemyPreferredRange);
722	        const float avoidRange = enemy.type == EnemyType::Sprinter ? 12.0f : kEnemyAvoidDistance;
723	
724	        Vec3 movement{};
725	        if (dist > preferredRange) {
726	            movement = dir;
727	        } else if (dist < avoidRange) {
728	            movement = dir * -0.65f;
729	        }
730	
731	        if (length(movement) > 0.0f) {
732	            enemy.pos += normalize(movement) * (kEnemySpeed * waveSpeedScale * enemySpeedMultiplier(enemy.type) * dt);
733	            keepInsideArena(enemy.pos);
734	        }
735	
736	        if (dist <= (enemy.type == EnemyType::Sprinter ? 32.0f : 48.0f) && enemy.shootCooldown <= 0.0f) {
737	            spawnEnemyShot(game, enemy);
738	            addImpact(game, enemy.pos + Vec3{0.0f, 1.8f, 2.6f}, sf::Color(255, 160, 60), 2.2f, 0.16f);
739	            enemy.shootCooldown = randomFloat(kEnemyFireCooldownMin, kEnemyFireCooldownMax) * cooldownScale * enemyCooldownMultiplier(enemy.type);
740	        }
741	    }
742	
743	    while (aliveCount < desiredAliveEnemies(game) && game.enemiesRemainingToSpawn > 0) {
744	        Enemy enemy = spawnEnemy(game.wave);
745	        if (length(enemy.pos - game.player.pos) < 22.0f) {
746	            continue;
747	        }
748	        game.enemies.push_back(enemy);
749	        --game.enemiesRemainingToSpawn;
750	        ++aliveCount;
751	    }
752	
753	    if (aliveCount == 0 && game.enemiesRemainingToSpawn == 0) {
754	        if (game.wave >= kTargetWave) {
755	            game.won = true;
756	        } else {
757	            addImpact(game, game.player.pos + Vec3{0.0f, 4.0f, 0.0f}, sf::Color(120, 210, 255), 5.0f, 0.4f);
758	            game.killFlash = 0.35f;
759	            startWave(game, game.wave + 1);
760	        }
761	    }
762	}
