void drawImpact(const ImpactEffect& fx, const Vec3& cameraRight, const Vec3& cameraUp) {
    const float t = fx.age / std::max(0.001f, fx.lifetime);
    const float radius = fx.size * (0.4f + t * 1.8f);
    const sf::Color color(fx.color.r, fx.color.g, fx.color.b, static_cast<sf::Uint8>(255.0f * (1.0f - t)));
    const Vec3 right = cameraRight * radius;
    const Vec3 up = cameraUp * radius;

    glDisable(GL_LIGHTING);
    glDisable(GL_TEXTURE_2D);
    glDepthMask(GL_FALSE);
    setColor(color);
    glBegin(GL_QUADS);
    glVertex3f(fx.pos.x - right.x - up.x, fx.pos.y - right.y - up.y, fx.pos.z - right.z - up.z);
    glVertex3f(fx.pos.x + right.x - up.x, fx.pos.y + right.y - up.y, fx.pos.z + right.z - up.z);
    glVertex3f(fx.pos.x + right.x + up.x, fx.pos.y + right.y + up.y, fx.pos.z + right.z + up.z);
    glVertex3f(fx.pos.x - right.x + up.x, fx.pos.y - right.y + up.y, fx.pos.z - right.z + up.z);
    glEnd();
    glBegin(GL_LINES);
    glVertex3f(fx.pos.x - right.x * 1.25f, fx.pos.y - right.y * 1.25f, fx.pos.z - right.z * 1.25f);
    glVertex3f(fx.pos.x + right.x * 1.25f, fx.pos.y + right.y * 1.25f, fx.pos.z + right.z * 1.25f);
    glVertex3f(fx.pos.x - up.x * 1.25f, fx.pos.y - up.y * 1.25f, fx.pos.z - up.z * 1.25f);
    glVertex3f(fx.pos.x + up.x * 1.25f, fx.pos.y + up.y * 1.25f, fx.pos.z + up.z * 1.25f);
    glEnd();
    glDepthMask(GL_TRUE);
    glEnable(GL_TEXTURE_2D);
    glEnable(GL_LIGHTING);
}
void drawCrosshair(const sf::RenderWindow& window) {
    glMatrixMode(GL_PROJECTION);
    glPushMatrix();
    glLoadIdentity();
    glOrtho(0.0, static_cast<double>(window.getSize().x), static_cast<double>(window.getSize().y), 0.0, -1.0, 1.0);
    glMatrixMode(GL_MODELVIEW);
    glPushMatrix();
    glLoadIdentity();

    glDisable(GL_LIGHTING);
    glDisable(GL_TEXTURE_2D);
    glDisable(GL_DEPTH_TEST);
    glColor3f(1.0f, 1.0f, 1.0f);

    const float cx = static_cast<float>(window.getSize().x) * 0.5f;
    const float cy = static_cast<float>(window.getSize().y) * 0.5f;
    glBegin(GL_LINES);
    glVertex2f(cx - 10.0f, cy);
    glVertex2f(cx + 10.0f, cy);
    glVertex2f(cx, cy - 10.0f);
    glVertex2f(cx, cy + 10.0f);
    glEnd();

    glEnable(GL_DEPTH_TEST);
    glEnable(GL_TEXTURE_2D);
    glEnable(GL_LIGHTING);
    glPopMatrix();
    glMatrixMode(GL_PROJECTION);
    glPopMatrix();
    glMatrixMode(GL_MODELVIEW);
}

void renderHud(sf::RenderWindow& window, const GameState& game, const HudAssets& hud) {
    window.pushGLStates();

    const sf::Vector2f barPos(28.0f, 24.0f);
    const sf::Vector2f barSize(280.0f, 24.0f);

    sf::RectangleShape panel(sf::Vector2f(360.0f, 118.0f));
    panel.setPosition(16.0f, 16.0f);
    panel.setFillColor(sf::Color(8, 12, 18, 185));
    panel.setOutlineThickness(2.0f);
    panel.setOutlineColor(sf::Color(90, 170, 220, 180));
    window.draw(panel);

    sf::RectangleShape healthBg(barSize);
    healthBg.setPosition(barPos);
    healthBg.setFillColor(sf::Color(40, 24, 24, 220));
    window.draw(healthBg);

    sf::RectangleShape healthFill(sf::Vector2f(barSize.x * clampf(game.player.health / 100.0f, 0.0f, 1.0f), barSize.y));
    healthFill.setPosition(barPos);
    healthFill.setFillColor(sf::Color(220, 70, 70));
    window.draw(healthFill);

    sf::RectangleShape killBg(sf::Vector2f(barSize.x, 18.0f));
    killBg.setPosition(barPos.x, barPos.y + 42.0f);
    killBg.setFillColor(sf::Color(28, 36, 52, 220));
    window.draw(killBg);

    sf::RectangleShape killFill(sf::Vector2f(barSize.x * clampf(static_cast<float>(game.wave - 1) / static_cast<float>(std::max(1, kTargetWave - 1)), 0.0f, 1.0f), 18.0f));
    killFill.setPosition(barPos.x, barPos.y + 42.0f);
    killFill.setFillColor(sf::Color(255, 194, 84));
    window.draw(killFill);

    if (hud.hasFont) {
        sf::Text hp("HP", hud.font, 18);
        hp.setPosition(barPos.x, barPos.y - 4.0f);
        hp.setFillColor(sf::Color::White);
        window.draw(hp);

        sf::Text hpValue(std::to_string(static_cast<int>(std::round(game.player.health))), hud.font, 18);
        hpValue.setPosition(barPos.x + barSize.x - 46.0f, barPos.y - 4.0f);
        hpValue.setFillColor(sf::Color::White);
        window.draw(hpValue);

        sf::Text kills("KILLS", hud.font, 18);
        kills.setPosition(barPos.x, barPos.y + 32.0f);
        kills.setFillColor(sf::Color::White);
        window.draw(kills);

        std::ostringstream killText;
        killText << "Wave " << game.wave << " / " << kTargetWave;
        sf::Text killsValue(killText.str(), hud.font, 18);
        killsValue.setPosition(barPos.x + barSize.x - 78.0f, barPos.y + 32.0f);
        killsValue.setFillColor(sf::Color::White);
        window.draw(killsValue);

        std::ostringstream status;
        status << "Alive " << aliveEnemyCount(game) << "  |  Incoming " << game.enemiesRemainingToSpawn << "  |  Kills " << game.kills;
        sf::Text controls(status.str(), hud.font, 16);
        controls.setPosition(barPos.x, barPos.y + 70.0f);
        controls.setFillColor(sf::Color(210, 222, 235));
        window.draw(controls);

        if (game.won || game.lost) {
            sf::RectangleShape banner(sf::Vector2f(520.0f, 92.0f));
            banner.setOrigin(banner.getSize() * 0.5f);
            banner.setPosition(static_cast<float>(window.getSize().x) * 0.5f, 90.0f);
            banner.setFillColor(sf::Color(10, 15, 24, 210));
            banner.setOutlineColor(game.won ? sf::Color(255, 194, 84) : sf::Color(240, 90, 90));
            banner.setOutlineThickness(3.0f);
            window.draw(banner);

            sf::Text headline(game.won ? "Arena Cleared" : "You Were Eliminated", hud.font, 34);
            headline.setPosition(banner.getPosition().x - 160.0f, banner.getPosition().y - 34.0f);
            headline.setFillColor(sf::Color::White);
            window.draw(headline);

            sf::Text subline("Press R to restart", hud.font, 22);
            subline.setPosition(banner.getPosition().x - 92.0f, banner.getPosition().y + 8.0f);
            subline.setFillColor(sf::Color(220, 230, 240));
            window.draw(subline);
        }
    }

    if (game.damageFlash > 0.0f) {
        sf::RectangleShape damage(sf::Vector2f(static_cast<float>(window.getSize().x), static_cast<float>(window.getSize().y)));
        damage.setFillColor(sf::Color(255, 40, 40, static_cast<sf::Uint8>(110.0f * game.damageFlash)));
        window.draw(damage);
    }

    if (game.killFlash > 0.0f) {
        sf::RectangleShape kill(sf::Vector2f(static_cast<float>(window.getSize().x), static_cast<float>(window.getSize().y)));
        kill.setFillColor(sf::Color(255, 214, 80, static_cast<sf::Uint8>(55.0f * game.killFlash)));
        window.draw(kill);
    }

    window.popGLStates();
}
void renderScene(sf::RenderWindow& window, const GameState& game, const HudAssets& hud) {
    const sf::Vector2u size = window.getSize();
    const float aspect = size.y == 0 ? 1.0f : static_cast<float>(size.x) / static_cast<float>(size.y);

    glViewport(0, 0, static_cast<GLint>(size.x), static_cast<GLint>(size.y));
    glClearColor(0.57f, 0.74f, 0.96f, 1.0f);
    glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);

    glMatrixMode(GL_PROJECTION);
    glLoadIdentity();
    setupPerspective(70.0f, aspect, 0.5f, 500.0f);

    const Vec3 aim = forwardFromAngles(game.player.yawDeg, game.player.pitchDeg);
    const Vec3 cameraTarget = game.player.pos + Vec3{0.0f, 3.8f, 0.0f};
    const Vec3 eye = cameraTarget - flatForward(game.player.yawDeg) * 15.0f + Vec3{0.0f, 8.0f, 0.0f} - Vec3{0.0f, aim.y * 4.0f, 0.0f};
    const Vec3 target = cameraTarget + aim * 24.0f;

    glMatrixMode(GL_MODELVIEW);
    glLoadIdentity();
    setupLookAt(eye, target, Vec3{0.0f, 1.0f, 0.0f});

    const GLfloat lightPos[] = {40.0f, 90.0f, 30.0f, 1.0f};
    glLightfv(GL_LIGHT0, GL_POSITION, lightPos);

    drawArena(game);
    drawPlayer(game.player);
    for (const auto& enemy : game.enemies) {
        if (enemy.alive) {
            drawEnemy(enemy);
        }
    }
    for (const auto& projectile : game.projectiles) {
        drawProjectile(projectile);
    }

    drawCrosshair(window);
    window.display();
}
}  // namespace

int main() {
    sf::ContextSettings settings;
    settings.depthBits = 24;
    settings.stencilBits = 8;
    settings.antialiasingLevel = 4;
    settings.majorVersion = 2;
    settings.minorVersion = 1;

    sf::RenderWindow window(
        sf::VideoMode(kWindowWidth, kWindowHeight),
        "C++ 3D Shooter",
        sf::Style::Default,
        settings);
    window.setVerticalSyncEnabled(true);
    window.setMouseCursorVisible(false);
    window.setActive(true);

    initOpenGlState();
    const HudAssets hud = loadHudAssets();

    GameState game;
    resetGame(game);
    sf::Mouse::setPosition(sf::Vector2i(static_cast<int>(window.getSize().x / 2), static_cast<int>(window.getSize().y / 2)), window);

    sf::Clock frameClock;
    while (window.isOpen()) {
        sf::Event event{};
        while (window.pollEvent(event)) {
            if (event.type == sf::Event::Closed) {
                window.close();
            }
            if (event.type == sf::Event::LostFocus) {
                window.setMouseCursorVisible(true);
            }
            if (event.type == sf::Event::GainedFocus) {
                window.setMouseCursorVisible(false);
                sf::Mouse::setPosition(sf::Vector2i(static_cast<int>(window.getSize().x / 2), static_cast<int>(window.getSize().y / 2)), window);
            }
        }

        const float dt = std::min(0.03f, frameClock.restart().asSeconds());
        if (window.hasFocus()) {
            handleMouseLook(window, game);
        }

        const InputState input = readInput();
        if (input.reset) {
            resetGame(game);
            sf::Mouse::setPosition(sf::Vector2i(static_cast<int>(window.getSize().x / 2), static_cast<int>(window.getSize().y / 2)), window);
        }

        updatePlayer(game, input, dt);
        updateProjectiles(game, dt);
        updateEnemies(game, dt);

        window.setTitle(buildTitle(game));
        renderScene(window, game, hud);
    }

    return 0;
}

